# In-repo support library consumed only by vpn_extension_module in the
# same repository: keep every own-namespace symbol (incl. vtable/guard
# needed for cross-DSO virtual dispatch under cfi_cross_dso) on mangled
# names; hide std inline instances and _init/_fini.
{
  global:
    _Z*4OHOS*;
  local:
    *;
};
